{
  "summary": "Unless terminated sooner, the initial term of the Strategic Alliance Agreement is three years from the Effective Date of 15 April 2009, with automatic one-year renewals unless notice is given 90 days before the end of the term.",
  "evidence": [
    {
      "passage_id": 4,
      "quote": "This Strategic Alliance Agreement (this \"Agreement\"), effective as of 15 April, 2009 (the \"Effective Date\"), is by and between Information  System Associates, Inc., a Florida Corporation whose registered office is 1151 Southwest 30th Street, Suite E, Palm City FL, 34990 (\"ISA\") and  Rubicon Software Group plc, a company registered under the laws of England and Wales (Registered Company No. 5701810) whose registered  office is Rubicon House, Guildford Road, West End, Surrey GU24 9PW (\"Rubicon\")."
    },
    {
      "passage_id": 5,
      "quote": "Unless terminated sooner, the term of this Agreement shall begin on the Effective Date and continue for three (3) years  thereafter (the \"Initial Term\") and shall automatically renew for additional one (1) year terms on the terms and conditions set forth herein (each a  \"Renewal Term\" and collectively, the \"Term\") unless either party gives the other Party Notice of its intention to terminate this Agreement ninety  (90) days before the end of the Initial Term or Renewal Term, if any."
    }
  ]
}
